What does this program print? (`Console.Write` adds no new line.)

```csharp
static int F()
{
    try
    {
        Console.Write("A");
        return 1;
    }
    finally
    {
        Console.Write("B");
    }
}
Console.Write(F());
Console.WriteLine();
```

What does this program print?

```csharp
try
{
    string? name = null;
    ArgumentNullException.ThrowIfNull(name);
}
catch (ArgumentException e) when (e is not ArgumentNullException)
{
    Console.WriteLine("bad argument");
}
catch (ArgumentException)
{
    Console.WriteLine("missing argument");
}
catch (Exception)
{
    Console.WriteLine("something else");
}
```

What does this program print?

```csharp
using (var a = new Noisy("A"))
using (var b = new Noisy("B"))
{
    using var c = new Noisy("C");
}
Console.WriteLine();

sealed class Noisy(string name) : IDisposable
{
    public void Dispose() => Console.Write(name);
}
```

What does this program print?

```csharp
static bool Log(string where)
{
    Console.Write(where);
    return false;
}

try
{
    try
    {
        throw new TimeoutException();
    }
    catch (Exception) when (Log("1"))
    {
        Console.Write("X");
    }
    finally
    {
        Console.Write("2");
    }
}
catch (TimeoutException)
{
    Console.Write("3");
}
Console.WriteLine();
```
